export const LEVEL_OBJECT_TYPES = Object.freeze(Object.values(LevelObjectType));
export const LEVEL_OBJECT_TYPE_NAMES = Object.freeze([...LEVEL_OBJECT_TYPES, ...Object.keys(LEVEL_OBJECT_TYPE_ALIASES)]);
export const LEVEL_OBJECT_TYPE_BY_CLASS_NAME = Object.freeze(Object.fromEntries(Object.values(GAME_OBJECT_CONTRACTS).map(contract => [contract.className, contract.type])));

function freezeLevelDefaults(value) {
    if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
    for (const child of Object.values(value)) freezeLevelDefaults(child);
    return Object.freeze(value);
}

